entries[187326] = { ["name"] = "Halbfertiges Runenschmiedemuster", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 48 katalogisierte Forschung zu erzeugen.\n\"Während des Schmiedens wurde ein wichtiger Schritt ausgelassen, doch ob das mit Absicht geschah, ist nicht bekannt.\"\nVerkaufspreis:" }
entries[187327] = { ["name"] = "Verschlüsseltes korthianisches Tagebuch", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 48 katalogisierte Forschung zu erzeugen.\n\"Das Tagebuch enthält reichlich Notizen in einer uralten Schrift.\"\nVerkaufspreis:" }
entries[187328] = { ["name"] = "Zerrissene Kosmologiekarte", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 100 katalogisierte Forschung zu erzeugen.\n\"Ihr erkennt, dass sie sich auf den Kosmos bezieht, doch sie ähnelt keiner Karte, die ihr je in Azeroth gesehen habt.\"" }
entries[187329] = { ["name"] = "Präparat eines alten Gottes", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 150 katalogisierte Forschung zu erzeugen.\n\"Das Auge schwebt in einer unbekannten Flüssigkeit und wirkt makellos konserviert.\"\nVerkaufspreis:" }
entries[187330] = { ["name"] = "Naarusplitterfragmente", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 150 katalogisierte Forschung zu erzeugen.\n\"Dieses Bruchstück scheint leicht zu leuchten, doch Euch ist nicht klar, ob das nur am Licht liegt oder ob mehr dahinter steckt.\"\nVerkaufspreis:" }
entries[187331] = { ["name"] = "Zerschlissene Faevorlagen", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 150 katalogisierte Forschung zu erzeugen.\n\"Auf diesem zerrissenen Pergament sind ein paar bekannte Fae abgebildet.\"\nVerkaufspreis:" }
entries[187332] = { ["name"] = "Gerettete Seite der Stimmen", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 100 katalogisierte Forschung zu erzeugen.\n\"Die Überreste dieser Seite beinhalten die Namen von Bediensteten, die einst der Richterin gedient haben.\"\nVerkaufspreis:" }
entries[187333] = { ["name"] = "Kern eines unbekannten Titanen", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 300 katalogisierte Forschung zu erzeugen.\n\"Ein Titanenkern, der für die nähere Untersuchung mehrmals auseinandergenommen wurde.\"\nVerkaufspreis:" }
entries[187334] = { ["name"] = "Zerschmetterte Leerentafel", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 100 katalogisierte Forschung zu erzeugen.\n\"Aus dieser Tafel sickern Leerenenergie und Geflüster, das man besser ignoriert.\"\nVerkaufspreis:" }
entries[187335] = { ["name"] = "Maldraxxuslarvenpanzer", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 300 katalogisierte Forschung zu erzeugen.\n\"Dieser Panzer verbreitet den unverkennbaren Geruch von Maldraxxus. Ihr wisst schon, welchen ich meine.\"\nVerkaufspreis:" }
