entries[187466] = { ["name"] = "Korthianisches Chiffrenbuch", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt Eure Funde bei Archivar Roh-Suir ab, um 100 katalogisierte Forschung zu erzeugen.\n\"Auf den Seiten scheinen sich Übersetzungen für Hunderte von Sprachen zu befinden. Der ursprüngliche Schlüssel für die Chiffre ist nicht enthalten und wurde vermutlich nur an die Gelehrten der Bediensteten übermittelt.\"\nVerkaufspreis:" }
