entries[187496] = { ["name"] = "Reiche der Schattenlande", ["text"] = "Wird beim Aufheben gebunden\n\"Eine handschriftliche Kopie eines Buches, das die einzigartige Geschichte der Schattenlande beschreibt.\"\nVerkaufspreis:" }
entries[187497] = { ["name"] = "Zierliche Klingenschwingenfigur", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses aus einem Stück Bernstein geschnitzte Exemplar ist äußerst detailliert.\"\nVerkaufspreis:" }
entries[187498] = { ["name"] = "Extravagant bestickter Beutel", ["text"] = "Wird beim Aufheben gebunden\n\"Man weiß nicht, wer diese Beutel aus luxuriösem Stoff fertigte, doch unter den wenigen verbleibenden Gelehrten der Bediensteten sind sie noch verbreitet.\"\nVerkaufspreis:" }
entries[187499] = { ["name"] = "Gemeißelte Elethiumkugel", ["text"] = "Wird beim Aufheben gebunden\n\"Einige Bereiche dieser Kugel erinnern an die Landschaften einiger von Euch bereister Reiche der Schattenlande, während Euch andere absolut unbekannt sind.\"\nVerkaufspreis:" }
entries[187500] = { ["name"] = "Aufwendig geätzter Brieföffner", ["text"] = "Wird beim Aufheben gebunden\n\"Wird nach Angaben der Bediensteten zum Brechen der Siegel von katalogisierten Tagebüchern genutzt und ist nur selten zum Öffnen von Briefen im Einsatz.\"\nVerkaufspreis:" }
entries[187501] = { ["name"] = "Verstehen der Vorsehung", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Leitfaden, der sehr ausführlich immer wieder auf die unermüdliche Hingabe für das umfassende Konzept der Vorsehung eingeht.\"\nVerkaufspreis:" }
entries[187503] = { ["name"] = "Bündel archivierter Forschung", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 500 katalogisierte Forschung.\"\n<Zum Öffnen rechtsklicken>" }
entries[187504] = { ["name"] = "Mikanikos' regenerative Vorrichtung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stellt die Vitalität eines Verbündeten wieder her. (2 Sek. Abklingzeit)\n\"Erschaffen von den klügsten Köpfen der Bastion. Diese Vorrichtung sollte die Heilung von Kyrianern, Steingeborenen, Nachtfae und Maldraxxi ermöglichen.\"" }
entries[187505] = { ["name"] = "Supercooler Drachenkopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n60 ( 60)\n\"Noch warmer Kopf von Drachenherz.\"" }
entries[187506] = { ["name"] = "Kondensierte Animasphäre", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt dieses Medium in der Schmiede der Bande Eurer Sammlung hinzu." }
entries[187507] = { ["name"] = "Adaptives Rüstungsfragment", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt dieses Medium in der Schmiede der Bande Eurer Sammlung hinzu." }
entries[187508] = { ["name"] = "Tragekorb für abgerichtete Gromits", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Beschwört einen Schatzschnüfflergromit, der dabei hilft, Relikte und Schätze in Korthia und im Schlund zu finden. (1 Min Abklingzeit)\n\"Seine feine Nase spürt alles auf.\"" }
entries[187511] = { ["name"] = "Erinnerung an die elysische Macht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nElysische Macht Runenschnitzmacht Sofort\nErhöht die Dauer von 'Speer der Bastion' um 4 Sek. Euer kritischer Schaden ist um 25% erhöht, solange Ihr Euch im Effektbereich von 'Speer der Bastion' aufhaltet.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Krieger" }
entries[187512] = { ["name"] = "Foliant der winzigen Sünden", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Hilft einem Kleintier, für seine Sünden Buße zu tun und in das von ihm verdiente Jenseits überzugehen.\n\nKann nur von Mitgliedern des Pakts der Venthyr oder jenen verwendet werden, die bei den Venthyr Ruhmstufe 80 erreicht haben. (1 Min Abklingzeit)\n\"Ein Ritualfoliant, der die Methoden der Venthyr erläutert, selbst die kleinsten Kreaturen von ihren Sünden zu erlösen.\"" }
entries[187515] = { ["name"] = "Theotars bodenlose Teekanne", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Schenkt Euch oder einem Gruppenmitglied eine Tasse exquisiten Tee ein. (5 Sek. Abklingzeit)" }
entries[187516] = { ["name"] = "Firims Schmiedeanzapfer", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entzieht aufgegebenen Schmieden in Zereth Mortis Restenergie und seltene Protomaterialien. (3 Sek. Abklingzeit)\n\"Eines der vielen uralten weggeworfenen Geräte, die man in Zereth Mortis findet.\"" }
entries[187517] = { ["name"] = "Animaquellenprisma", ["text"] = "Anima\nWird beim Aufheben gebunden\nBenutzen: Lagert 250 gespeicherte Anima im Animareservoir Eures Pakts ein.\n\"Ein verborgener Schatz aus den Legenden.\"\nVerkaufspreis:" }
entries[187519] = { ["name"] = "Übriggebliebene Neopartikel", ["text"] = "Questgegenstand\n\"Ein Baustein ewiger Gebilde.\"" }
entries[187520] = { ["name"] = "Leicht geschütteltes Geschenk", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[187524] = { ["name"] = "Schlüsselsteinaffix hinzufügen: Gequält", ["text"] = "Dauer: 12 std. (Realzeit)\nBenutzen: Fügt einem mythischen Schlüsselstein das Affix Gequält hinzu.\nVerkaufspreis:" }
entries[187525] = { ["name"] = "Seelenverzerrter Todeswandler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein heulender Vortex aus gepeinigten Seelen. Wer ihn als Reittier erwählt, tut es, um eine beeindruckende Toleranz gegenüber Schmerz und Leid zu beweisen.\"\nErfolg:\nSchlüsselsteinmeister von Shadowlands: Saison 2\nKategorie:\nDungeons" }
entries[187526] = { ["name"] = "Verdächtige Liste", ["text"] = "Wird beim Aufheben gebunden\n\"Vielleicht könnte sich jemand dafür interessieren?\"" }
entries[187527] = { ["name"] = "Aeonmatrix", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein wertvolles Objekt, bei dem sich eine gründliche Untersuchung lohnt.\"\nVerkaufspreis:" }
