entries[187542] = { ["name"] = "Jaithys die Gefängnisklinge", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n101 - 168 Schaden Geschwindigkeit 3.60\n(37.4 Schaden pro Sekunde)\n+50 Stärke\n+75 Ausdauer\nErhöht Eure kritische Trefferwertung um + 33.\nErhöht Eure Tempowertung um + 67.\nBenutzen: Verschlingt eine geringere Waffe und zerstört sie, um Jaithys' Macht zu nähren.\nVerkaufspreis:" }
