entries[187550] = { ["name"] = "Schattenstahlraspeln", ["text"] = "\"Köstlich. Gut ausbalanciert. Meine Komplimente an den Schmied.\"\nVerkaufspreis:" }
entries[187551] = { ["name"] = "Kleine korthianische Vorratstruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Handwerksmaterialien, Gold und Korthitkristall.\"\n<Zum Öffnen rechtsklicken>" }
entries[187552] = { ["name"] = "Perfekt gefälschte Legitimation", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHals\n+37 Ausdauer\nErhöht Eure Tempowertung um + 58.\nErhöht Eure Meisterschaftswertung um + 66.\nAnlegen: Eure Angriffe und Fähigkeiten haben eine Chance, Euren Primärwert für 15 Sek. um 14 zu erhöhen.\nBenutzen: Legt eine Mittlerverkleidung an, die Euch uneingeschränkten Zugang zum Verhüllten Markt gewährt.\n\nKann nur in Tazavesh, dem Verhüllten Markt, verwendet werden.\nVerkaufspreis:" }
