entries[187595] = { ["name"] = "Gunst des Hippogryphen von Val'sharah", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen Hippogryphen von Val'sharah beschwört. Das ist ein Flugreittier.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese majestätischen Hippogryphen kommen einer Kreatur des Smaragdgrünen Traums näher als alle anderen Bewohner Azeroths. Von ihnen als Reiter angenommen zu werden, ist eine wahre Leistung.\"\nVerkäufer:\nAridormi\nZone:\nDalaran\nKosten:\n5.000" }
