entries[187602] = { ["name"] = "Firims Motivator", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stürmt auf verwirrte Automas innerhalb von 12 Metern zu und verpasst ihnen einen ordentlichen Hieb, sodass sie Euch gehorchen. (3 Sek. Abklingzeit)\n\"Ein mysteriöses Gerät, das die Handlungen von Automas beeinflusst.\"" }
entries[187603] = { ["name"] = "Tee des Wahnsinnigen Herzogs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Trinkt den Tee des Wahnsinnigen Herzogs, was Eure Hauptwert, Euer Tempo, Eure kritische Trefferchance oder Eure Vielseitigkeit 4 Stunden lang erhöht.\n\nEs kann immer nur der Effekt eines Tees des Wahnsinnigen Herzogs gleichzeitig aktiv sein. (1 Stunde Abklingzeit)" }
entries[187604] = { ["name"] = "Verzauberkunstbedarfzustellung von den Verheerten Inseln", ["text"] = "Wird beim Aufheben gebunden\n\"Eine Lieferung Verzauberkunstbedarf von Dalarans ureigener Verzauberkunsthändlerin Ildine Sorgenspeer.\"\n<Zum Öffnen rechtsklicken>" }
