entries[187612] = { ["name"] = "Schlüssel des fließenden Wassers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Öffnet eine Relikttruhe in Korthia.\nErfordert Forschungsstufe 2 beim Archivarskodex.\n\"Die Oberfläche des Schlüssels hat schon bessere Tage gesehen, denn hier haben sich die tückischen Gewässer, die einst das Ästuarium des Erwachens auszeichneten, ausgetobt.\"\nVerkaufspreis:" }
entries[187613] = { ["name"] = "Schlüssel der inneren Kammern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Öffnet eine Relikttruhe in Korthia.\nErfordert Forschungsstufe 2 beim Archivarskodex.\n\"Das Insigne auf diesem Schlüssel lässt darauf schließen, dass er in Verbindung mit den großen Schatzkammern steht.\"\nVerkaufspreis:" }
entries[187614] = { ["name"] = "Schlüssel der vielen Gedanken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Öffnet eine Relikttruhe in Korthia.\nErfordert Forschungsstufe 2 beim Archivarskodex.\n\"Die von Hand eingebrannten Siegel an der Seite des Schlüssels könnten unter Umständen die Mysterien von Relikten innerhalb des Quorums des Suchers offenbaren.\"\nVerkaufspreis:" }
entries[187615] = { ["name"] = "Kugelfragment", ["text"] = "Questgegenstand\n\"Von Klauen- und Bissspuren übersät.\"" }
entries[187617] = { ["name"] = "Gehärteter Djaradinstahl", ["text"] = "Baumaterial\nWird beim Aufheben gebunden\nDauer: 10 min\nHandwerksmaterial\n\"Von Rüstungen von im Kampf besiegten Gegnern und von eroberten Gebäuden der Djaradin gesammelt.\"\nVerkaufspreis:" }
entries[187618] = { ["name"] = "Schaltkreis von Standort Oeth", ["text"] = "Questgegenstand\n\"Wie dieses Gerät genau funktioniert, ist unklar, aber die Automas erhalten dadurch Zugang zu Standort Oeth.\"" }
entries[187619] = { ["name"] = "Windende Saat", ["text"] = "Questgegenstand\n\"Ranken winden sich um den inneren Kern. Sie sind in Bewegung und voller Leben.\"" }
entries[187620] = { ["name"] = "Windende Saat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n60 ( 60)\n\"Metallene Zahnräder und lebende Ranken, miteinander verschmolzen.\"" }
entries[187621] = { ["name"] = "Konstruktionsschreiben", ["text"] = "Baumaterial\nWird beim Aufheben gebunden\n\"Autorisiert den Konstruktionsbeginn an verschiedenen Orten auf den Dracheninseln.\"\nVerkaufspreis:" }
entries[187626] = { ["name"] = "Verdächtige Papiere", ["text"] = "Questgegenstand\nEinzigartig (10)\n60 ( 60)\n\"Auf diesen Papierfetzen sind seltsame Kritzeleien... sehr wahrscheinlich ein Code.\"" }
entries[187628] = { ["name"] = "Wiederherstellungsmatrix", ["text"] = "Questgegenstand\nEinzigartig\n\"Für die Automas ein Instrument von bedeutender Macht. Allerdings ist die Energie dieses Geräts nahezu erschöpft.\"\nVerkaufspreis:" }
entries[187629] = { ["name"] = "Herzlichtstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Herzlichtvombata als Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Erleuchteten\n- Ehrfürchtig\n\n\"Die Erleuchteten verehren alle Schöpfungen, welche die Ersten erschaffen haben, doch viele verspüren die größte Hingabe für die Vombatas von Zereth Mortis. Diese Wesen sind zu gleichen Teilen zuverlässige Packtiere und geliebte Begleiter.\"\nVerkäufer:\nVilo\nZone:\nZereth Mortis\nFraktion:\nDie Erleuchteten - Ehrfürchtig\nKosten:\n5.000" }
entries[187630] = { ["name"] = "Neugieriger Kristallschnüffler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die meisten Vombatas genießen es, sich durch den Untergrund zu graben, aber diese Schnüffler scheinen über die unfehlbare Fähigkeit zu verfügen, Kristalle ausfindig zu machen, die tief im Boden vergraben sind, und sammeln sich in der Nähe von großen Vorkommen.\"\nBeruf:\nProtoformsynthese" }
entries[187631] = { ["name"] = "Dunkler Vombata", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Bauplan, mit dem diese dunklen Vombatas synthetisiert werden können, scheint als Reaktion auf die Invasion der Schlundgebundenen entstand zu sein. Die daraus entstehenden Vombatas sehen zwar anders aus, nämlich dunkler, ähnlich den Invasoren, doch sie verhalten sich normal.\"\nBeruf:\nProtoformsynthese" }
entries[187632] = { ["name"] = "Geschmückter Vombata", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Rote Vombatas werden von den Erleuchteten als Glücksbringer betrachtet, da bei ihrer Ankunft in Zereth Mortis ein roter Vombata zugegen war.\"\nBeruf:\nProtoformsynthese" }
entries[187633] = { ["name"] = "Bufonidengitter", ["text"] = "Protoformsynthese\nHandwerksmaterial\n\"Ein mystisches Gitter für die Synthetisierung eines Bufoniden.\"" }
entries[187634] = { ["name"] = "Ambystidengitter", ["text"] = "Protoformsynthese\nHandwerksmaterial\n\"Ein mystisches Gitter für die Synthetisierung eines Ambystiden.\"" }
entries[187635] = { ["name"] = "Cervidengitter", ["text"] = "Protoformsynthese\nHandwerksmaterial\n\"Ein mystisches Gitter für die Synthetisierung eines Cerviden.\"" }
entries[187636] = { ["name"] = "Aurelidengitter", ["text"] = "Protoformsynthese\nHandwerksmaterial\n\"Ein mystisches Gitter für die Synthetisierung eines Aureliden.\"" }
entries[187637] = { ["name"] = "Navarros Rucksack", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Schnappt Euch Euren Lieblingsrucksack und auf geht's! (5 Sek. Abklingzeit)" }
entries[187638] = { ["name"] = "Todesläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese wilden Cerviden finden nur dann wahrlich Frieden, wenn sie durch die Länder des Todes streifen oder zwischen ihnen umherziehen.\"\nBeruf:\nProtoformsynthese" }
entries[187639] = { ["name"] = "Blasser majestätischer Cervid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Beim Anblick dieser majestätischen Wesen ist es nicht schwer, sich auszumalen, wie die Idee der Cerviden sich zu den Hirschen entwickelt hat, die jetzt Azeroth und andere sterbliche Welten durchstreifen.\"\nBeruf:\nProtoformsynthese" }
entries[187640] = { ["name"] = "Zügel des geweihten Protohirsches", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen geweihten Protohirsch als Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Erleuchteten\n- Respektvoll\n\n\"Nur die, die das höchste Ansehen der Erleuchteten genießen, bekommen die Zügel dieses seltenen Cerviden anvertraut.\"\nVerkäufer:\nVilo\nZone:\nZereth Mortis\nFraktion:\nDie Erleuchteten - Respektvoll\nKosten:\n5.000" }
entries[187641] = { ["name"] = "Zügel des gemarterten Zerethhirschs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Was auch immer ihr Zweck dieser Cerviden einst war, er ist seit Langem vergessen. Sie werden zwar nicht beherrscht, aber sie wurden durch die unvorgesehene Präsenz der Schlundgebundenen im heiligen Reich von Zereth Mortis verderbt.\"\nBeruf:\nProtoformsynthese" }
entries[187642] = { ["name"] = "Boshafter Kriegspirscher", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man einen boshaften Kriegspirscher beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Lasst die Allianz Staub schmecken, während Ihr einen majestätischen Protoformwolf reitet! Für die Horde!\"\nPvP:\nShadowlands: Saison 4\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[187644] = { ["name"] = "Boshafter Kriegspirscher", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man einen boshaften Kriegspirscher beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Lasst die Horde Staub schmecken, während Ihr einen majestätischen Protoformwolf reitet! Für die Allianz!\"\nPvP:\nShadowlands: Saison 4\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[187648] = { ["name"] = "Leerer Steinsuppenkessel", ["text"] = "Benutzen: Richtet einen Kessel Steinsuppe her, der mit köstlichen Zutaten gefüllt werden kann. Stellt die Suppe fertig, damit sie bis zu 70 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nDie fertige Suppe stellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 53 erhöht.\nVerkaufspreis:" }
entries[187650] = { ["name"] = "Stab der drakonischen Energien", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n5 - 7 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+20 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 6.\nKlassen: Rufer\nVerkaufspreis:" }
