entries[187652] = { ["name"] = "Ruferstiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Kette\n7 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nKlassen: Rufer\nVerkaufspreis:" }
