entries[187654] = { ["name"] = "Ruferkappe", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 4.\nKlassen: Rufer\nVerkaufspreis:" }
entries[187655] = { ["name"] = "Ruferbeinwickel", ["text"] = "Wird beim Aufheben gebunden\nBeine Kette\n10 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\n+ 4 Vielseitigkeit\nKlassen: Rufer\nVerkaufspreis:" }
