entries[187657] = { ["name"] = "Rufergürtel", ["text"] = "Wird beim Aufheben gebunden\nTaille Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\n+ 4 Vielseitigkeit\nKlassen: Rufer\nVerkaufspreis:" }
entries[187658] = { ["name"] = "Ruferarmbinden", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nKlassen: Rufer\nVerkaufspreis:" }
entries[187659] = { ["name"] = "Schließkiste des Abenteurers", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Ausrüstung für andere Klassenspezialisierungen.\"\n<Zum Öffnen rechtsklicken>" }
entries[187660] = { ["name"] = "Vespidenflatterer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Flatterer ist ein übergroßer Vespidarbeiter, erschaffen, um einen Reiter auf seinem Rücken zu tragen. Anstatt einer Königin zu folgen, verlässt er sich in allen Lebenslagen auf die Führung seines Reiters.\"\nBeruf:\nProtoformsynthese" }
entries[187662] = { ["name"] = "Seltsamer Schleim", ["text"] = "Einzigartig\n\"Diese Substanz scheint auf die Aureliden von Zereth Mortis eine gewisse Anziehungskraft auszuüben, aber sie lässt sich mit keinem Köder verbinden. Jemand, der sich mit Tiefseekreaturen auskennt, weiß womöglich, was man damit machen kann.\"" }
entries[187663] = { ["name"] = "Bronzeflügelvespid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Bronzeflügelvespiden sind ein Ergebnis des Versuchs, eine Vespidenkönigin ohne weitere Mitglieder eines neuen Schwarms zu synthetisieren. Obwohl bisher noch kein Sterblicher herausgefunden hat, wie man einen Stock synthetisiert, stellen die Bronzeflügel selbst in ihrem aktuellen Zustand verlässliche Reittiere dar.\"\nBeruf:\nProtoformsynthese" }
entries[187664] = { ["name"] = "Geschmiedeter Tückenflügler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es gibt kaum etwas, das einen das Leben so sehr spüren lässt wie ein Ritt durch das Reich des Todes auf dem Rücken eines Wesens, das einen hasst.\"\nBeruf:\nProtoformsynthese" }
entries[187665] = { ["name"] = "Summ", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Summ summ summ, summ summ! Summ summ summ summ summ. Summ summ summ, summ summ summ.\"\nBeruf:\nProtoformsynthese" }
entries[187666] = { ["name"] = "Wüstenschwingenjäger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Wüstenschwingenjäger wurden im Dienste der großen Vorhersehung erschaffen, um die weiten Himmel der vergessenen Reiche der Schattenlande zu erfüllen.\"\nBeruf:\nProtoformsynthese" }
entries[187667] = { ["name"] = "Schlundadaptierter Raptora", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Seit dem Übergriff des Kerkermeisters sind neue Raptoras durch Zereth Mortis synthetisiert worden, die dem verderbenden Einfluss des Schlunds widerstehen können.\"\nBeruf:\nProtoformsynthese" }
entries[187668] = { ["name"] = "Raptorasturzflieger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Raptorasturzflieger ist eine der grausamsten Ausprägungen dieser Art, perfekt an seine ökologische Nische angepasst. Die Sturzflieger, die heutzutage synthetisiert werden, benötigen keine weitere Anpassungen und sind identisch mit denen, die in der Vergangenheit erschaffen wurden.\"\nBeruf:\nProtoformsynthese" }
entries[187669] = { ["name"] = "Serenade", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese wunderschönen Heliciden zeigen sich nur bei Nacht. Sind sie wohlgestimmt, lassen ihre Schneckenhäuser eine fröhliche Melodie erklingen.\"\nBeruf:\nProtoformsynthese" }
entries[187670] = { ["name"] = "Bronzener Helicid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einige Heliciden von Zereth Mortis haben von Natur aus seltsam metallische Schneckenhäuser. Sie sind üblicherweise bronzefarben, und ihr Metall unterscheidet sich nicht von dem, mit dem sogar Anfänger unter den Minenarbeitern umgehen können, mit der Einschränkung, dass die Konstruktion dieser Kreatur die Fähigkeiten von Anfängern mehr als überfordern würde.\"\nBeruf:\nProtoformsynthese" }
entries[187671] = { ["name"] = "Gescheiterter Flitzopodenprototyp", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Kreatur ist nicht von den Ersten entworfen worden, sondern stattdessen von einem unbekannten Wesen in dem Versuch, einen sehr schnellen Läufer zu kreieren. Es blieb bei dem Versuch, da dieses Reittier doch sehr langsam ist.\"\nBeruf:\nProtoformsynthese" }
entries[187672] = { ["name"] = "Scharlachroter Helicid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die ungewöhnliche rötliche Färbung dieses Heliciden ist eindeutig beabsichtigt, und der einzige andere Unterschied zwischen diesem und anderen Heliciden ist das ungewöhnliche Fehlen von Schleim.\"\nBeruf:\nProtoformsynthese" }
entries[187673] = { ["name"] = "Kryptischer Aurelid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Chiffren der Ersten entziehen sich dem Verständnis der Sterblichen. Ein seltsamer Effekt dieser Sprache ist, dass sich einige Aureliden aus unbekannten Gründen zu jenen Sterblichen hingezogen fühlen, die danach streben, das Mysterium zu ergründen.\"\nErfolg:\nVon A bis Zereth\nKategorie:\nSchattenlande" }
entries[187674] = { ["name"] = "Tiefenpirscher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Tiefenpirscher beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein paar dieser Quallen wurden in Zereth Mortis gewildert und sind über Bord gegangen, als das Schiff der Wilderer sank. Sie haben in den Tiefen des Großen Meeres ein neues Zuhause gefunden.\"\nHandelsposten" }
entries[187675] = { ["name"] = "Schimmernder Aurelid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Obschon er einst geschaffen wurde, das Mausoleum der Ersten zu verteidigen, folgt er jetzt nach der Erfüllung seiner Primärfunktion gehorsam Euren Befehlen.\"\nErfolg:\nRuhm des Mausoleumsschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[187676] = { ["name"] = "Tiefensternpolyp", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Tiefensternaureliden beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als einer der letzten verbleibenden Polypen eines scheuen Wesens fühlt sich dieser Aurelid sowohl im Wasser als auch in der Luft gleichermaßen wohl.\"\nBeute von:\nHirukon\nZone:\nZereth Mortis" }
entries[187677] = { ["name"] = "Genesiskrabbler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Jene Erleuchteten, die Tarachniden beobachtet haben, glauben, dass diese Art zu den ersten Wesen gehörte, die durch die Länder von Zereth Mortis streiften.\"\nBeruf:\nProtoformsynthese" }
entries[187678] = { ["name"] = "Tarachnidenkriecher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Tarachniden hausen in den finstersten Ecken von Zereth Mortis und verlassen sie nur, um zu jagen (oder um manchmal einen Reiter auf ihrem Rücken zu tragen).\"\nBeruf:\nProtoformsynthese" }
entries[187679] = { ["name"] = "Unergründlicher Krabbler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Tarachniden bewegen sich mit einer Absicht, die niemand nachvollziehen kann, und scheinen nur einem höheren Ruf zu folgen. Was auch immer sich dahinter verbergen mag, es scheint regelmäßige Hilfe für Sterbliche zu beinhalten, die ein Reittier benötigen. Für den Moment zumindest.\"\nBeruf:\nProtoformsynthese" }
entries[187680] = { ["name"] = "Boshafter Kriegsquaker", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man einen boshaften Kriegsquaker beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese Kreaturen stürzen sich mit so viel Begeisterung in den Kampf, dass sich ihr Quaken fast schon wie ein \"FÜR DIE HORDE!\" anhört.\"\nPvP:\nSchattenlande: Saison 3\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[187681] = { ["name"] = "Boshafter Kriegsquaker", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man einen boshaften Kriegsquaker beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese Kreaturen stürzen sich mit so viel Begeisterung in den Kampf, dass sich ihr Quaken fast schon wie ein \"FÜR DIE ALLIANZ!\" anhört.\"\nPvP:\nSchattenlande: Saison 3\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[187682] = { ["name"] = "Verlustverzerrter Todeswandler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese raue, wirbelnde Energie ist in kohäsiver Form gebunden und unterwirft sich nur dem Willen derjenigen, die stark und entschlossen genug sind, sie zu binden.\"\nErfolg:\nSchlüsselsteinmeister von Shadowlands: Saison 3\nKategorie:\nDungeons" }
entries[187683] = { ["name"] = "Goldplattenbufonid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser gepanzerte Bufonid ist immer bereit, ins Kampfgetümmel zu springen... vorausgesetzt, der Kampf ist wirklich ganz in der Nähe. Im Notfall kann er mehrere Male springen und so letztendlich den Kampf erreichen.\"\nBeruf:\nProtoformsynthese" }
entries[187684] = { ["name"] = "Eindämmungsfalle", ["text"] = "Questgegenstand\nBenutzen: Fängt das Ziel in einem Eindämmungsfeld ein, sodass es weiter untersucht werden kann. (15 Sek. Abklingzeit)\n\"Sorgt für die Sicherheit und Unversehrtheit von Forschern.\"" }
entries[187685] = { ["name"] = "Schwarzstahlfragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n60 ( 60)\n\"Diesem Klumpen Stahl entströmt die Magie des Kerkermeisters...\"" }
entries[187689] = { ["name"] = "Dunkelmond-Tanzparty", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört eine Tanzfläche und zeigt, was Ihr könnt! (30 Min Abklingzeit)" }
entries[187690] = { ["name"] = "Jägerhose", ["text"] = "Wird beim Anlegen gebunden\nBeine Kette\n3 Rüstung\nHaltbarkeit 40 / 40\nVerkaufspreis:" }
