entries[187693] = { ["name"] = "Jägergürtel", ["text"] = "Wird beim Anlegen gebunden\nTaille Kette\n2 Rüstung\nHaltbarkeit 18 / 18\nVerkaufspreis:" }
entries[187694] = { ["name"] = "Jägerarmschienen", ["text"] = "Wird beim Anlegen gebunden\nHandgelenk Kette\n1 Rüstung\nHaltbarkeit 18 / 18\nVerkaufspreis:" }
entries[187695] = { ["name"] = "Jägerhandschuhe", ["text"] = "Wird beim Anlegen gebunden\nHände Kette\n2 Rüstung\nHaltbarkeit 18 / 18\nVerkaufspreis:" }
entries[187696] = { ["name"] = "Der Wolf, der Wolpertinger und andere haarige Geschichten", ["text"] = "\"Eine abgegriffene, mit goldenem Garn gebundene Gedichtsammlung.\"\n<Zum Lesen rechtsklicken>" }
entries[187699] = { ["name"] = "Erste Blume", ["text"] = "Handwerksmaterial\n\"Dieser seltene und wunderschöne Prototyp einer Blume gedeiht im Land der Ersten an tödlichen Orten.\"\nVerkaufspreis:" }
entries[187700] = { ["name"] = "Progeniumerz", ["text"] = "Handwerksmaterial\n\"Kann aus Ablagerungen und Elementaren gewonnen werden, die man in den schroffsten und gefährlichsten Gegenden von Zereth Mortis findet.\"\nVerkaufspreis:" }
entries[187701] = { ["name"] = "Protogenischer Pelz", ["text"] = "Handwerksmaterial\n\"Spielercharaktere mit der Kürschnerfertigkeit können diese seltenen Tierhäute von den stärksten Kreaturen erbeuten, die es in Zereth Mortis gibt.\"\nVerkaufspreis:" }
entries[187702] = { ["name"] = "Urplacoderm", ["text"] = "Handwerksmaterial\n\"Dieser rätselhafte Fisch taucht nur gelegentlich in Gruppen auf, um auf Nahrungssuche zu gehen. Unter anderen Umständen sieht man ihn nur selten.\"\nVerkaufspreis:" }
entries[187703] = { ["name"] = "Seidene Protofaser", ["text"] = "Handwerksmaterial\n\"Wird von einigen der mächtigsten Würmer und Spinnen von Zereth Mortis produziert und von Spielercharakteren mit der Schneiderfertigkeit verwendet.\"\nVerkaufspreis:" }
entries[187704] = { ["name"] = "Protofleisch", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
