entries[187791] = { ["name"] = "Kismetrischer Reif", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert einen kismetrischen Reif mit 100 Spurenenigmenten, 10 Ephemerasträhnen und 5 eidolischen Partikeln.\n\"Unendlich modifizierbar. Unzählige Formen sind möglich.\"\nVerkaufspreis:" }
