entries[187795] = { ["name"] = "Archetyp der Entdeckung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Archetyp der Entdeckung beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[187796] = { ["name"] = "Vertrag: Die Erleuchteten", ["text"] = "Benutzen: Schließt einen Vertrag mit den Erleuchteten ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in den Schattenlanden abschließt.\nBenötigt Die Erleuchteten\n- Freundlich" }
entries[187797] = { ["name"] = "Technik: Vertrag: Die Erleuchteten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Vertrag: Die Erleuchteten herstellt.\nBenötigt Inschriftenkunde der Schattenlande (75)\nBenötigt Die Erleuchteten\n- Respektvoll\n\nVertrag: Die Erleuchteten\nBenutzen: Schließt einen Vertrag mit den Erleuchteten ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in den Schattenlanden abschließt.\nBenötigt Die Erleuchteten\n- Freundlich\nBenötigt Stille Tinte (3), Protogenischer Pelz" }
entries[187798] = { ["name"] = "Wühlender Vombata", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren wühlenden Vombata beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[187802] = { ["name"] = "Kosmischer Heiltrank", ["text"] = "Benutzen: Stellt 72000 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[187803] = { ["name"] = "Archetyp der Bewegung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Archetyp der Bewegung beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[187804] = { ["name"] = "Rezept: Leerer Steinsuppenkessel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen leeren Steinsuppenkessel herstellt.\nBenötigt Kochkunst der Schattenlande (75)\n\nLeerer Steinsuppenkessel\nBenutzen: Richtet einen Kessel Steinsuppe her, der mit köstlichen Zutaten gefüllt werden kann. Stellt die Suppe fertig, damit sie bis zu 70 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nDie fertige Suppe stellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 53 erhöht.\nVerkaufspreis:\nBenötigt Leerer Kessel , Verdunkelter Stein , Erfrischendes Quellwasser (5)" }
entries[187805] = { ["name"] = "Vantusrune: Mausoleum der Ersten", ["text"] = "Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Mausoleum der Ersten ein, was Eure Vielseitigkeit um 1875 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:" }
entries[187806] = { ["name"] = "Vantusrunentechnik: Mausoleum der Ersten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Mausoleum der Ersten herstellt.\nBenötigt Inschriftenkunde der Schattenlande (100)\nVerkaufspreis:\nVantusrune: Mausoleum der Ersten\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Mausoleum der Ersten ein, was Eure Vielseitigkeit um 1875 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leuchtende Tinte (8), Umbraltinte (8), Stille Tinte (3), Protogenischer Pelz" }
entries[187808] = { ["name"] = "Losung", ["text"] = "Questgegenstand\nEinzigartig (3)\n\"Benötigt, um Zugang zum Gefäß zu erhalten.\"" }
entries[187809] = { ["name"] = "Schlüssel des Beherrschers", ["text"] = "Questgegenstand\n\"Ein Schlüssel zu den Zellen der Schlundgebundenen in den Endlosen Sanden.\"" }
