entries[187821] = { ["name"] = "Bar-Fusans Hackklinge", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n81 - 136 Schaden Geschwindigkeit 3.60\n(30.1 Schaden pro Sekunde)\n+40 Stärke\n+60 Ausdauer\nErhöht Eure kritische Trefferwertung um + 43.\nErhöht Eure Meisterschaftswertung um + 37.\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[187822] = { ["name"] = "Anforderung eines Überläufers", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n60 ( 60)\n\"Eine Schriftrolle, die eine Waffenrequisition zur Unterstützung der maldraxxischen Überläufer in Revendreth schildert.\"\nVerkaufspreis:" }
entries[187823] = { ["name"] = "Magisch regulierter Automakern", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance durch Fähigkeiten, in Zielnähe Automakern zu erzeugen, der Schaden und Heilung verursacht.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:" }
entries[187824] = { ["name"] = "Formel: Magisch regulierter Automakern", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen magisch regulierten Automakern herstellt.\nBenötigt Verzauberkunst der Schattenlande (100)\nVerkaufspreis:\nMagisch regulierter Automakern\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance durch Fähigkeiten, in Zielnähe Automakern zu erzeugen, der Schaden und Heilung verursacht.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Ewiger Kristall (5), Progeniumerz , Unsterblichkeitssplitter (5)" }
entries[187825] = { ["name"] = "Kosmisches Protogewebe", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erhöht die Vermeidung und beim Erleiden von Schaden besteht eine Chance, dass Ihr geheilt werdet.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:" }
entries[187826] = { ["name"] = "Formel: Kosmisches Protogewebe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein kosmisches Protogewebe herstellt.\nBenötigt Verzauberkunst der Schattenlande (100)\nVerkaufspreis:\nKosmisches Protogewebe\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erhöht die Vermeidung und beim Erleiden von Schaden besteht eine Chance, dass Ihr geheilt werdet.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Heiliger Splitter (10), Seidene Protofaser (6), Unsterblichkeitssplitter (5)" }
entries[187827] = { ["name"] = "Infusion: Leichenläuterung", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance, dass Ihr Ressourcen erhaltet, wenn Ihr einen Gegner tötet, der Erfahrung oder Ehre gewährt.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:" }
entries[187828] = { ["name"] = "Rezept: Infusion: Leichenläuterung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Infusion: Leichenläuterung herstellt.\nBenötigt Alchemie der Schattenlande\n(100)\nVerkaufspreis:\nInfusion: Leichenläuterung\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance, dass Ihr Ressourcen erhaltet, wenn Ihr einen Gegner tötet, der Erfahrung oder Ehre gewährt.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Erste Blume (6), Nachtschatten (8), Destilliertes Todesextrakt (5)" }
entries[187829] = { ["name"] = "Akkolarischer Harmonisierungsstein", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance durch Fähigkeiten, in der Nähe ein Partikel zu erzeugen. Sammelt es für Primärwert (15 Sek.).\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:" }
entries[187830] = { ["name"] = "Vorlage: Akkolarischer Harmonisierungsstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen akkolarischen Harmonisierungsstein herstellt.\nBenötigt Juwelierskunst der Schattenlande\n(100)\nVerkaufspreis:\nAkkolarischer Harmonisierungsstein\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Chance durch Fähigkeiten, in der Nähe ein Partikel zu erzeugen. Sammelt es für Primärwert (15 Sek.).\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Progeniumerz (7), Formbarer Draht (5), Oribrant (5), Umbryl (5)" }
entries[187831] = { ["name"] = "Reinluftsegelerweiterung", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erhöht die Geschwindigkeit und Reitgeschwindigkeit am Boden in den Schattenlanden.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:" }
entries[187832] = { ["name"] = "Bauplan: Reinluftsegelerweiterung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Reinluftsegelerweiterungen herstellt.\nBenötigt Ingenieurskunst der Schattenlande (100)\nVerkaufspreis:\nReinluftsegelerweiterung\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erhöht die Geschwindigkeit und Reitgeschwindigkeit am Boden in den Schattenlanden.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Progeniumerz (4), Seidene Protofaser (6), Handvoll Laestritbolzen (10), Poröses Scheuermittel (20)" }
entries[187833] = { ["name"] = "Piekfeiner Pocopoc", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Pocopoc kann ein neues Kostüm tragen. (3 Sek. Abklingzeit)" }
entries[187834] = { ["name"] = "Gequältes Banner des Opportunen", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt ein Banner auf, das Eure Erfolge im Kampf gegen die Gequälten zur Schau stellt. (10 Min Abklingzeit)" }
entries[187835] = { ["name"] = "Replizierende Essenz", ["text"] = "Questgegenstand\n\"Mehr Krankheit als Geschenk. Repliziert sich schnell, bis sie den Wirt getötet hat.\"" }
entries[187836] = { ["name"] = "Unberechenbare Genesismatrix", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erlittener Schaden erzeugt Funken der Macht. Bei 5 Stapeln wird der nächste Angreifer geschockt und erleidet kosmischen Schaden.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:" }
entries[187837] = { ["name"] = "Bauplan: Unberechenbare Genesismatrix", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Progenitorschaltkreise herstellt.\nBenötigt Ingenieurskunst der Schattenlande (100)\nVerkaufspreis:\nUnberechenbare Genesismatrix\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erlittener Schaden erzeugt Funken der Macht. Bei 5 Stapeln wird der nächste Angreifer geschockt und erleidet kosmischen Schaden.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Progeniumerz (5), Handvoll Laestritbolzen (10), Zeitlich gesegnete Sprungfeder (2), Wurmdurchsetztes Getriebe (4)" }
entries[187839] = { ["name"] = "Tonblocker", ["text"] = "Questgegenstand\nBenutzen: Entfernt trügerische Zauber vom Ziel und enthüllt möglicherweise einen Schreckenslord." }
entries[187840] = { ["name"] = "Glitzerflügel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Lasst Eurer inneren Fee mit diesen glitzernden Flügeln freien Lauf!\n\nKann nur von Mitgliedern des Pakts der Nachtfae oder jenen verwendet werden, die bei den Nachtfae Ruhmstufe 80 erreicht haben. (5 Min Abklingzeit)" }
