entries[187847] = { ["name"] = "Vorlage: Verschlingeressenzstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Verschlingeressenzstein herstellt.\nBenötigt Juwelierskunst der Schattenlande\n(100)\nVerkaufspreis:\nVerschlingeressenzstein\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Wenn Ihr einen Gegner tötet, erhöht sich Euer höchster Sekundärwert für 20 Sek. Bis zu 5-mal stapelbar.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Progeniumerz (7), Formbarer Draht (4), Wutauge (8)" }
entries[187848] = { ["name"] = "Rezept: Pflegende Rüstungspolitur", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine pflegende Rüstungspolitur herstellt.\nBenötigt Alchemie der Schattenlande\n(100)\nVerkaufspreis:\nPflegende Rüstungspolitur\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Erhöht die Dauer von Effekten durch Fläschchen, Elixiere und Sättigungseffekte um 50%.\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Erste Blume (6), Todesblüte (25), Destilliertes Todesextrakt (5)" }
