entries[187860] = { ["name"] = "Mortismurmel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Beschwört eine Sphäre von Zereth Mortis, um darauf herumzurollen. Kann nur im Freien verwendet werden. (1 Min, 40 Sek. Abklingzeit)\n\"Eine Reisemethode, so langsam wie die Zeit selbst.\"" }
entries[187862] = { ["name"] = "Schlangenseele", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[187863] = { ["name"] = "Ephemeraschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Der Schlüssel ist abwechselnd da... und nicht da. Es ist schwer, die Details auszumachen... oder zu erkennen, ob er wirklich real ist.\"\nVerkaufspreis:" }
entries[187865] = { ["name"] = "Stachelige Protomaschen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Auf Eurer Haut sträuben sich 10 Min. lang kleine Stacheln, sodass erlittene Nahkampfangriffe dem Angreifer körperlichen Schaden zufügen. Kann nur in Zereth Mortis benutzt werden. (5s Abklingzeit) (5 Min Abklingzeit)" }
entries[187866] = { ["name"] = "Beschleunigende Sehnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Die Nerven geben schneller Signale ab, was 10 Min. lang die Bewegungsgeschwindigkeit um 10% und das Tempo um 5% erhöht. Kann nur in Zereth Mortis benutzt werden. (5 Min Abklingzeit)" }
