entries[187895] = { ["name"] = "Späherkarte: Die Gefahren Draenors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in Draenor auf.\nBenötigt den Erfolg \"Erforscher Draenors\".\n\"Eine kurze Liste der wenigen sicheren Zufluchtsorte, die man in Draenor findet. Die Liste enthält außerdem die örtlichen Bräuche, die man an jedem dieser Orte beachten sollte.\"" }
entries[187896] = { ["name"] = "Späherkarte: Der Sturmbräuführer für Pandaria", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in Pandaria auf.\nBenötigt den Erfolg \"Erforscher Pandarias\".\n\"Eine heitere Geschichte über Li Lis jüngste Abenteuer in Pandaria, samt kulinarischer Empfehlungen ihres Onkels Chen.\"" }
entries[187897] = { ["name"] = "Späherkarte: Die Konsequenzen des Kataklysmus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten auf, die während des Kataklysmus erstellt wurden.\nBenötigt den Erfolg \"Erforscher des Kataklysmus\".\n\"Ein seltener fraktionsübergreifender Bericht, der die unzähligen Folgen des von Todesschwinge ausgelösten Weltenbebens von Azeroth zusammenträgt.\"" }
entries[187898] = { ["name"] = "Späherkarte: Der wahre Preis des Nordendfeldzugs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in Nordend auf.\nBenötigt den Erfolg \"Erforscher Nordends\".\n\"Ein detaillierter Bericht einer Argentumkreuzfahrerin über alle militärischen Operationen, die zur Verfolgung des Lichkönigs unternommen wurden.\"" }
entries[187899] = { ["name"] = "Späherkarte: Die vielen Kuriositäten der Scherbenwelt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in der Scherbenwelt auf.\nBenötigt den Erfolg \"Erforscher der Scherbenwelt\".\n\"Eine Beschreibung der verschiedenen Biome und der unglaublichen Flora der Scherbenwelt, aus der Feder eines abenteuerlustigen Alchemisten.\"" }
entries[187900] = { ["name"] = "Späherkarte: Die Wunder von Kul Tiras und Zandalar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Findet Flugpunkte und deckt Karten in Kul Tiras und Zandalar auf.\nBenötigt den Erfolg \"Erforscher von Battle for Azeroth\".\n\"Ein Duo aus einem Goblin und einer Gnomin beschreibt seine vielen Entdeckungen auf den zwei Inseln.\"" }
entries[187901] = { ["name"] = "Adlerseele", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nNehmt an sieben verschiedenen Aufführungen im Sternseeamphitheater teil." }
