entries[187908] = { ["name"] = "Firims Ersatzschmiedeanzapfer", ["text"] = "Wird beim Aufheben gebunden\nDauer: 8 std. (Realzeit)\nBenutzen: Entzieht aufgegebenen Schmieden in Zereth Mortis Restenergie und seltene Protomaterialien. (3 Sek. Abklingzeit)\n\"Eine weniger stabile Version von Firims Schmiedeanzapfer.\"" }
entries[187909] = { ["name"] = "Instabile Eindämmungsfalle", ["text"] = "Wird beim Aufheben gebunden\nDauer: 8 std. (Realzeit)\nBenutzen: Fängt das Ziel in einem Eindämmungsfeld ein, sodass es weiter untersucht werden kann. (15 Sek. Abklingzeit)\n\"Eine weniger stabile Version der Eindämmungsfalle.\"" }
entries[187911] = { ["name"] = "Sinistre \"Suppe\"", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 9375 / 5 * 20) Gesundheit und ( 12500 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[187913] = { ["name"] = "Stiefel des Schleimomantenlehrlings", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Zieht für 3 Min. eine Schleimspur hinter Euch her, wohin Ihr auch geht.\n\nKann nur von denjenigen verwendet werden, die den Nekrolords die Treue geschworen oder Ruhmstufe 80 bei den Nekrolords erreicht haben. (5 Min Abklingzeit)" }
entries[187914] = { ["name"] = "Kapitän Noteos unbenutzte Augenklappe", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187915] = { ["name"] = "Stinkender Blobfisch", ["text"] = "Einzigartig\n\"Riecht so scheußlich, wie er aussieht.\"\nVerkaufspreis:" }
entries[187916] = { ["name"] = "Spiralkrallententakel", ["text"] = "Einzigartig\n\"Das Tentakel windet sich stetig, als ob es sich nach etwas Unerreichbarem strecken würde.\"\nVerkaufspreis:" }
entries[187917] = { ["name"] = "Tee des Wahnsinnigen Herzogs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Trinkt den Tee des Wahnsinnigen Herzogs, was Eure Hauptwert, Euer Tempo, Eure kritische Trefferchance oder Eure Vielseitigkeit 4 Stunden lang erhöht.\n\nEs kann immer nur der Effekt eines Tees des Wahnsinnigen Herzogs gleichzeitig aktiv sein. (3 Sek. Abklingzeit)" }
entries[187920] = { ["name"] = "Flossenfisch", ["text"] = "Einzigartig\nVerkaufspreis:" }
entries[187922] = { ["name"] = "Flossenfisch", ["text"] = "Einzigartig\n\"Selbst im Tod versucht er noch, Euch wieder durch die Finger zu gleiten.\"\nVerkaufspreis:" }
entries[187923] = { ["name"] = "Aurelidenköder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bringt den Aurelidenköder an Eurer Angelrute an.\n\"Zieht Quallen und mit ihnen verwandte Kreaturen an.\"\nVerkaufspreis:" }
entries[187925] = { ["name"] = "Äonenwasser", ["text"] = "Questgegenstand\n\"Sprudelt vor seltsamer Energie über. Ist das wirklich sicher?\"" }
entries[187928] = { ["name"] = "Archetyp der Metamorphose", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Archetyp der Metamorphose beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[187930] = { ["name"] = "Technik: Mal der majestätischen Fleddermaus", ["text"] = "Benutzen: Lehrt Euch, wie man ein Mal der majestätischen Fleddermaus herstellt.\nStellt ein Mal der majestätischen Fleddermaus her.\nBenötigt Inschriftenkunde der Schattenlande (100)\nVerkaufspreis:\nMal der majestätischen Fleddermaus\nKlassen: Druide\nBenutzen: Schaltet die Option für die majestätische Fleddermaus als Fluggestalt beim Barbier frei.\nVerkaufspreis:\nBenötigt Dunkles Pergament , Leuchtende Tinte (8), Umbraltinte (24)" }
