entries[187937] = { ["name"] = "Technik: Mal der zobelschwarzen Ardenmotte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Mal der zobelschwarzen Ardenmotte herstellt.\nStellt ein Mal der zobelschwarzen Ardenmotte her.\nBenötigt Inschriftenkunde der Schattenlande (100)\nBenötigt Hof der Nacht\n- Wohlwollend\nVerkaufspreis:\nMal der zobelschwarzen Ardenmotte\nKlassen: Druide\nBenutzen: Schaltet die Option für die zobelschwarze Ardenmotte als Reisegegestalt beim Barbier frei.\nVerkaufspreis:\nBenötigt Dunkles Pergament , Leuchtende Tinte (8), Umbraltinte (24)" }
entries[187940] = { ["name"] = "Komponentenbehälter", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Behälter, der dazu dient, beim Durchführen von Experimenten Materialien aufzubewahren.\"" }
entries[187941] = { ["name"] = "Erschöpfter Automakern", ["text"] = "Questgegenstand\nBenutzen: Zieht Energie aus besiegten Animaten in den erschöpften Kern. (3 Sek., 500 Ms Abklingzeit)" }
