entries[187987] = { ["name"] = "Hopsenden Bufoniden rufen", ["text"] = "Questgegenstand\nBenutzen: Ruft den hopsenden Bufoniden zurück, falls er verschwunden oder tot ist. (1 Min Abklingzeit)" }
