entries[187997] = { ["name"] = "Rüstungsschutz für ewige Erbstücke", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Wertet Erbstückrüstungen, Schmuckstücke oder Gegenstände für die Schildhand auf, sodass sie bis Stufe 60 aufsteigen können.\n\nFunktioniert nur bei Erbstücken, die auf Stufe 50 aufsteigen können." }
entries[187998] = { ["name"] = "Waffenscheide für ewige Erbstücke", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Wertet Erbstückwaffen auf, sodass sie bis Stufe 60 aufsteigen können.\n\nFunktioniert nur bei Erbstücken, die auf Stufe 50 aufsteigen können." }
entries[187999] = { ["name"] = "Angelportal", ["text"] = "Questgegenstand\nBenutzen: Schafft eine Öffnung in der Membran der Gewässer von Zereth Mortis, die genutzt werden kann, um Kreaturen dorthin zu locken. (15 Sek. Abklingzeit)" }
entries[188000] = { ["name"] = "Paket des Hainpflegers", ["text"] = "Anima\nWird beim Aufheben gebunden\nBenutzen: Lagert 250 gespeicherte Anima im Animareservoir Eures Pakts ein.\n\"Enthält viele animareiche Samen.\"\nVerkaufspreis:" }
entries[188002] = { ["name"] = "Zerbrochener Helm", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Erprobt die Macht des zerbrochenen Helms. (2 Sek. Abklingzeit)\n\"Eine zerschmetterte Hälfte des Helms der Herrschaft.\"" }
entries[188003] = { ["name"] = "Kiste mit edlen Revendrethtropfen", ["text"] = "Anima\nWird beim Aufheben gebunden\nBenutzen: Lagert 250 gespeicherte Anima im Animareservoir Eures Pakts ein.\n\"Eine Sammlung einiger der ältesten veredelten Animamischungen von Denathrius.\"\nVerkaufspreis:" }
entries[188004] = { ["name"] = "Kiste mit animaversetzten Teilen", ["text"] = "Anima\nWird beim Aufheben gebunden\nBenutzen: Lagert 250 gespeicherte Anima im Animareservoir Eures Pakts ein.\n\"Mit Anima durchtränkt, um Monstrositäten von höchster Qualität zu erschaffen.\"\nVerkaufspreis:" }
entries[188005] = { ["name"] = "Animagebadete Klinge", ["text"] = "Anima\nWird beim Aufheben gebunden\nBenutzen: Lagert 250 gespeicherte Anima im Animareservoir Eures Pakts ein.\n\"Ein Meisterwerk der Schmiedekunst.\"\nVerkaufspreis:" }
