entries[188252] = { ["name"] = "Ketten der Herrschaft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 [Beweglichkeit oder Stärke]\nBenutzen: Rammt einen Stachel in Euer Ziel, der 7116 körperlichen Schaden verursacht und für 20 Sek. eine Kettenverbindung zwischen Euch schafft. Solange die Kette besteht, werden 25% des dem Ziel zugefügten Schadens in ihr gespeichert, bis zu maximal 3019 Schaden.\n\nWenn Ihr Euch von Eurem Ziel entfernt, wird die Kette herausgerissen und die gespeicherte Schadensmenge wird allen Gegnern innerhalb von 8 Metern um das Ziel als Schattenschaden zugefügt. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[188253] = { ["name"] = "Narben der brüderlichen Zwietracht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Befestigt eine Rune der Herrschaft an Euch, die Euch Macht gewährt... zu einem gewissen Preis.\nBenutzen: Fügt eine weitere hinzu. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[188254] = { ["name"] = "Grimmige Finsternis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 Intelligenz\nBenutzen: Manifestiert einen Quasar, der Euer Ziel umkreist und ihm im Verlauf von 7 Sek. 3622 kosmischen Schaden zufügt.\n\nNach 7 Sek. stabilisiert sich der Quasar und erschafft einen Ereignishorizont, der 10 Sek. lang anhält und Euch innerhalb seines Effektbereichs 319 Tempo gewährt. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[188255] = { ["name"] = "Das Herz des Schwarms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 Stärke\nBenutzen: Beschwört den Schwarm herauf. Verliert die Fähigkeit, Zauber zu wirken oder anzugreifen, verwandelt sich aber in einen Schwarm gefräßiger Heuschrecken. Dies erhöht die Geschwindigkeit um 71 sowie den Lebensraub um 354 und verursacht ( 3439 * 3) Schattenschaden, der im Verlauf von 3 Sek. auf alle Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich pro getroffenem Gegner für bis zu 5 Gegner. (3 Min Abklingzeit)\nVerkaufspreis:" }
