entries[188261] = { ["name"] = "Zudringlicher Gedankenkäfig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 [Beweglichkeit oder Stärke]\nBenutzen: Erschafft eine Verbindung tief in den Gedanken Eures Ziels, die Euer Ausweichen um 222 erhöht und ihm im Verlauf von 6 Sek. [Quellwert] Gesundheit entzieht.\n\nWenn die Verbindung bei Ablauf des Effekts noch intakt ist, zersplittern die Gedanken des Ziels, was Gegnern innerhalb von 8 Metern um das Ziel 1091 Schattenschaden zufügt und sie für 3 Sek. entsetzt. (3 Min Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[188262] = { ["name"] = "Der Brüllende Löwe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nKlassen: Paladin , Priester , Schamane , Mönch , Druide , Rufer\nBenutzen: Kanalisiert für 3 Sek. Licht und erschafft einen Schutzbereich um Euch herum, der 30% des sämtlichen durch Verbündete darin erlittenen Schadens bis zu maximal 27443 Schaden absorbiert.\n\nEure kritischen Heilungen haben eine Chance, die Abklingzeit um 6 Sek. zu verringern.\n\nGilt nur für Heilerspezialisierungen. (10 Min Abklingzeit)\nVerkaufspreis:" }
entries[188263] = { ["name"] = "Intensitätskern des Rückgewinners", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nAnlegen: Wenn ein Automa in der Nähe stirbt, gebt Ihr Ephemera ab und heilt bis zu 5 Verbündete in der Nähe im Verlauf von 30 Sek. um ( 45 * 30) Gesundheit.\nBenutzen: Ruft einen Automasanitäter herbei, der bei Euch im Verlauf von 10 Sek. ( 14 * 10) Mana wiederherstellt, bevor er abläuft. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[188264] = { ["name"] = "Einschlag des Erdbrechers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nBenutzen: Lässt den Boden unter Euren Füßen erzittern, was im Verlauf von 12 Sek. 4445 Naturschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird. Der Schaden erhöht sich pro getroffenem Gegner.\n\nWährend des Bebens könnt Ihr tektonische Schwachstellen in der Nähe wahrnehmen. Wenn Ihr Euch an eine solche Schwachstelle bewegt, fügt Ihr allen Gegnern in der Nähe 635 Naturschaden zu. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[188265] = { ["name"] = "Truhe mit erhaltenen Schätzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Beweglichkeit\nAnlegen: Durchwühlt die Truhe regelmäßig nach einer neuen gestohlenen Waffe.\nBenutzen: Nehmt Euch eine Waffe aus der Truhe und erhaltet ihre Vorteile. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[188266] = { ["name"] = "Pulsierender Kluftsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nBenutzen: Platziert ein Rissportal vor Euch, das sich 1.5 Sek. lang auflädt und dann [ 1739 * (1 + Vielseitigkeit)] kosmischen Schaden in einer Linie auf alle Gegnern aufteilt. Das Portal stiehlt von der Realität an sich, wodurch Ihr einen Schild erhaltet, der 20 Sek. lang anhält und [ 4016 * (1 + Vielseitigkeit)] Schaden absorbiert.\n\nDer Schaden und die Absorption werden für jeden getroffenen Gegner erhöht, für bis zu 5 Gegner. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[188267] = { ["name"] = "Glocken des endlosen Festmahls", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nAnlegen: Eure Schadensfähigkeiten haben eine hohe Chance, den Duft köstlicher Seelenenergie auszumachen. Bis zu 100-mal stapelbar. Bei maximalen Stapeln bricht ein Schwarm Verschlinger hervor, die Euer Ziel beißen und ihm so 5733 körperlichen Schaden zufügen.\n\nEffekte, durch die sich Euer Ziel bewegt, erzeugen Bonusstapel.\nVerkaufspreis:" }
entries[188268] = { ["name"] = "Einfallsreichtumskern des Architekten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nAnlegen: Wenn ein Automa in der Nähe stirbt, werden Eure Abklingzeiten 30 Sek. lang um 5% schneller abgeschlossen.\nBenutzen: Ruft ein Bedienstetenautoma herbei, das im Verlauf von 8 Sek. ( 53 * 8) kosmischen Schaden auf Euer Ziel kanalisiert und dann zugrunde geht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[188269] = { ["name"] = "Taschenprotoschmiede", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, dass Ihr einen Verbündeten in der Taschenprotoschmiede fertigt, der Eure Gegner am Angreifen hindert, Euch im Kampf unterstützt und 5858 Schaden absorbiert.\nVerkaufspreis:" }
entries[188270] = { ["name"] = "Elegie der Ewigen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Vor den Ewigen weinend, verschreibt Ihr Euch ihren Diensten.\n\nErhöht Euren höchsten Sekundärwert um 40 und gewährt allen Gruppenmitgliedern, die ebenfalls Eurem Pakt dienen, 10% dieses Bonus.\nVerkaufspreis:" }
entries[188271] = { ["name"] = "Das erste Siegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Gewährt die Macht der Signaturfähigkeit Eures Pakts und erhöht die Vielseitigkeit für 20 Sek. um 645 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[188272] = { ["name"] = "Resonierender Kessel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nBenutzen: Feuert ein widerhallendes Geschoss auf Euer Ziel und löst damit einen Desintegrationskranz aus, der von der Position des Ziels ausgeht. Verursacht 6 Sek. lang alle 2 Sek. 189 Schaden. Schwillt 3-mal an, bevor der Effekt erneut einsetzt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[188273] = { ["name"] = "Glockenspiel des Bediensteten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nAnlegen: Eure Heilzauber und -fähigkeiten haben eine Chance, einen vorgefertigten Assistenten zu aktivieren, der 10 Sek. lang alle 1 Sek. eine Absorption in Höhe von 259 auf den am schwersten verletzten Verbündeten in Eurer Nähe anwendet.\nVerkaufspreis:" }
